import json
from fractions import Fraction as F

c = F(20, -24) - (2 + F(-3))
# f(x) = x^4/16 + 1 + x^2/8 + 0*x - c*x^3
f = {4: F(1, 16), 3: -c, 2: F(1, 8), 1: F(0), 0: F(1)}
# derivative
k = {e - 1: co * e for e, co in f.items() if e > 0}
deg = max(e for e, co in k.items() if co != 0)
poly = [k.get(e, F(0)) for e in range(deg, -1, -1)]  # highest first
lead = poly[0]

def divide(p, r):
    out = [p[0]]
    for a in p[1:]:
        out.append(a + out[-1] * r)
    rem = out.pop()
    return out, rem

cands = set()
for p in range(0, 13):
    for q in range(1, 13):
        cands.add(F(p, q))
        cands.add(F(-p, q))
cands = sorted(cands)

roots = {}
cur = poly[:]
changed = True
while len(cur) > 1 and changed:
    changed = False
    for r in cands:
        q, rem = divide(cur, r)
        if rem == 0:
            roots[r] = roots.get(r, 0) + 1
            cur = q
            changed = True
            break

